#!/usr/bin/env python3
"""
txcheck — verify a Bitcoin transaction is confirmed, using two independent
public explorers (mempool.space and blockstream.info). No API keys, stdlib only.

Usage:
  ./txcheck.py <txid> [<txid> ...] [--address ADDR] [--amount BTC] [--min-conf N] [--json]
  ./txcheck.py <txid> [<txid> ...] --bundle proof.json   # also save a bundle for the
                                                         # Bitcoin Tx Proof Verifier artifact

Exit codes:
  0  VERIFIED   (confirmed with >= min-conf on both sources, and expected output matches if given)
  1  NOT VERIFIED (unconfirmed, too few confirmations, sources disagree, or output mismatch)
  2  ERROR      (bad txid, tx not found, or network failure on every source)
"""
import argparse, json, os, re, sys, urllib.request, urllib.error
from datetime import datetime, timezone

SOURCES = {
    "mempool.space": "https://mempool.space/api",
    "blockstream.info": "https://blockstream.info/api",
}
TIMEOUT = 15


def get(url, as_json=True):
    req = urllib.request.Request(url, headers={"User-Agent": "txcheck/1.0"})
    with urllib.request.urlopen(req, timeout=TIMEOUT) as r:
        body = r.read().decode()
    return json.loads(body) if as_json else body.strip()


def query(name, base, txid):
    """Return dict for one source, or {'error': ...}."""
    try:
        tx = get(f"{base}/tx/{txid}")
        tip = int(get(f"{base}/blocks/tip/height", as_json=False))
    except urllib.error.HTTPError as e:
        if e.code in (400, 404):
            return {"source": name, "error": "transaction not found"}
        return {"source": name, "error": f"HTTP {e.code}"}
    except Exception as e:  # network, timeout, bad JSON
        return {"source": name, "error": str(e)}
    st = tx.get("status", {})
    confirmed = bool(st.get("confirmed"))
    height = st.get("block_height")
    confs = (tip - height + 1) if confirmed and height is not None else 0
    outs = [
        {"address": o.get("scriptpubkey_address", "(non-address output)"),
         "btc": o.get("value", 0) / 1e8}
        for o in tx.get("vout", [])
    ]
    return {
        "source": name,
        "confirmed": confirmed,
        "block_height": height,
        "block_hash": st.get("block_hash"),
        "block_time": st.get("block_time"),
        "tip_height": tip,
        "confirmations": confs,
        "fee_btc": tx.get("fee", 0) / 1e8,
        "outputs": outs,
    }


HEADERS_URL = "https://block-dn.org/headers/{start}"   # 100,000 raw headers per file
HEADERS_CACHE = os.path.expanduser("~/.cache/txcheck")


def headers_range(lo, hi):
    """Raw 80-byte headers for heights lo..hi inclusive (cached per 100k file).
    Source is untrusted: the verifier re-checks linkage + PoW against checkpoints."""
    os.makedirs(HEADERS_CACHE, exist_ok=True)
    out = b""
    for start in range(lo // 100000 * 100000, hi + 1, 100000):
        path = os.path.join(HEADERS_CACHE, f"h_{start}.bin")
        need_end = min(hi, start + 99999)
        if not os.path.exists(path) or os.path.getsize(path) < (need_end - start + 1) * 80:
            req = urllib.request.Request(HEADERS_URL.format(start=start), headers={"User-Agent": "txcheck/1.0"})
            with urllib.request.urlopen(req, timeout=120) as r, open(path, "wb") as f:
                f.write(r.read())
        blob = open(path, "rb").read()
        a, b = max(lo, start) - start, need_end - start + 1
        out += blob[a * 80:b * 80]
    if len(out) != (hi - lo + 1) * 80:
        raise ValueError("header source does not reach that height yet")
    return out


def fetch_bundle_entry(txid, cp_height=None):
    """Raw data the proof-verifier page checks itself (tx hex, merkleblock proof) plus
    explorer data (status, tip). Tries each source until one returns everything."""
    errs = []
    for name, base in SOURCES.items():
        try:
            e = {
                "txid": txid,
                "tx_hex": get(f"{base}/tx/{txid}/hex", as_json=False),
                "merkleblock_hex": get(f"{base}/tx/{txid}/merkleblock-proof", as_json=False),
                "status": get(f"{base}/tx/{txid}/status"),
                "tip_height": int(get(f"{base}/blocks/tip/height", as_json=False)),
                "source": name,
            }
            break
        except Exception as ex:  # unconfirmed tx has no merkle proof -> 400/404
            errs.append(f"{name}: {ex}")
    else:
        return {"txid": txid, "error": "; ".join(errs)}
    # block reward data: coinbase tx + its merkle proof (verified by the page), fees (explorer)
    bh = e["status"].get("block_hash")
    if bh:
        try:
            base = SOURCES[e["source"]]
            cbid = get(f"{base}/block/{bh}/txid/0", as_json=False)
            e["reward"] = {
                "coinbase_txid": cbid,
                "coinbase_hex": get(f"{base}/tx/{cbid}/hex", as_json=False),
                "coinbase_merkleblock_hex": get(f"{base}/tx/{cbid}/merkleblock-proof", as_json=False),
                "tx_fee_sats": get(f"{base}/tx/{txid}").get("fee"),
            }
            try:
                e["reward"]["total_fees_sats"] = get(f"https://mempool.space/api/v1/block/{bh}")["extras"]["totalFees"]
            except Exception:
                pass
        except Exception as ex:
            e["reward_error"] = str(ex)
    # headers from the block up to the next 2016-block checkpoint (main-chain proof)
    h = e["status"].get("block_height")
    if h is not None:
        cp = -(-h // 2016) * 2016
        if cp_height is not None and cp > cp_height:
            cp = cp_height if cp_height >= h else None
        try:
            if cp is not None and cp > h:
                e["chain_headers_hex"] = headers_range(h + 1, cp).hex()
            e["chain_to_height"] = cp
        except Exception as ex:
            e["chain_error"] = str(ex)
    return e


def main():
    p = argparse.ArgumentParser(description="Verify a Bitcoin tx is confirmed (2 explorers).")
    p.add_argument("txids", nargs="+", metavar="txid")
    p.add_argument("--bundle", metavar="FILE", help="also write a proof bundle JSON for the verifier artifact")
    p.add_argument("--checkpoints", metavar="FILE", help="checkpoints.json from chainverify.py (caps chain proof at its tip)")
    p.add_argument("--address", help="expected receiving address")
    p.add_argument("--amount", type=float, help="expected BTC to that address (needs --address)")
    p.add_argument("--min-conf", type=int, default=3, help="confirmations required (default 3)")
    p.add_argument("--json", action="store_true", help="print machine-readable JSON")
    a = p.parse_args()
    codes, entries = [], []
    for i, t in enumerate(a.txids):
        if i:
            print("\n" + "-" * 60)
        codes.append(check_one(t, a))
        txid = t.strip().lower()
        if a.bundle and re.fullmatch(r"[0-9a-f]{64}", txid):
            cph = json.load(open(a.checkpoints))["tip_height"] if a.checkpoints else None
            entries.append(fetch_bundle_entry(txid, cph))
    if a.bundle:
        bundle = {"format": "txproof-bundle-v1",
                  "created_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
                  "entries": entries}
        with open(a.bundle, "w") as f:
            json.dump(bundle, f)
        good = sum(1 for e in entries if "error" not in e)
        print(f"\nbundle: wrote {a.bundle} ({good}/{len(entries)} tx with proofs)", file=sys.stderr)
        for e in entries:
            if "error" in e:
                print(f"  no proof for {e['txid']}: {e['error']}", file=sys.stderr)
    return max(codes)


def check_one(txid_in, a):
    txid = txid_in.strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", txid):
        print(f"ERROR: txid must be 64 hex characters: {txid_in}", file=sys.stderr)
        return 2

    results = [query(n, b, txid) for n, b in SOURCES.items()]
    ok = [r for r in results if "error" not in r]
    problems = []

    if not ok:
        verdict, code = "ERROR", 2
        problems.append("no source could return this transaction")
    else:
        if len(ok) < len(results):
            problems.append("only one source answered — not independently confirmed")
        if len({(r["confirmed"], r["block_hash"]) for r in ok}) > 1:
            problems.append("sources DISAGREE on confirmation/block")
        confs = min(r["confirmations"] for r in ok)
        if not all(r["confirmed"] for r in ok):
            problems.append("UNCONFIRMED (in mempool) — can still be replaced or dropped")
        elif confs < a.min_conf:
            problems.append(f"only {confs} confirmation(s), need {a.min_conf}")

        match = None
        if a.address:
            paid = sum(o["btc"] for o in ok[0]["outputs"] if o["address"] == a.address)
            match = {"address": a.address, "paid_btc": round(paid, 8)}
            if paid == 0:
                problems.append(f"no output pays {a.address}")
            elif a.amount is not None and round(paid, 8) < round(a.amount, 8):
                problems.append(f"{a.address} received {paid:.8f} BTC, expected {a.amount:.8f}")

        verdict, code = ("VERIFIED", 0) if not problems else ("NOT VERIFIED", 1)

    report = {
        "txid": txid,
        "verdict": verdict,
        "min_conf": a.min_conf,
        "problems": problems,
        "sources": results,
        "checked_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
    }
    if a.address:
        report["expected_output"] = match if ok else None

    if a.json:
        print(json.dumps(report, indent=2))
        return code

    print(f"txid: {txid}")
    for r in results:
        if "error" in r:
            print(f"  [{r['source']}] ERROR: {r['error']}")
            continue
        when = (datetime.fromtimestamp(r["block_time"], timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
                if r["block_time"] else "-")
        state = f"confirmed, block {r['block_height']} ({when}), {r['confirmations']} conf" \
            if r["confirmed"] else "UNCONFIRMED"
        print(f"  [{r['source']}] {state}")
    if ok:
        print(f"  fee: {ok[0]['fee_btc']:.8f} BTC")
        print("  outputs:")
        for o in ok[0]["outputs"]:
            mark = "  <-- expected" if a.address and o["address"] == a.address else ""
            print(f"    {o['btc']:.8f} BTC  {o['address']}{mark}")
    print(f"\nVERDICT: {verdict}")
    for pr in problems:
        print(f"  - {pr}")
    return code


if __name__ == "__main__":
    sys.exit(main())

"""Layer-2 growth proof ledger: bidirectional, evidence-first, no live payments.

This is a local accounting/state-machine model. It does not connect to Lightning,
create invoices, hold keys, route payments, or move funds.
"""
from __future__ import annotations
import hashlib
import json
from dataclasses import dataclass
from datetime import datetime, timezone

SCHEMA = "paradox-layer2-growth/v1"
DIRECTIONS = ("FORWARD", "BACKWARD")


def canonical(value) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()


def digest(value) -> str:
    return hashlib.sha256(canonical(value)).hexdigest()


@dataclass(frozen=True)
class GrowthIntent:
    intent_id: str
    asset: str
    amount_msat: int
    purpose: str
    source_ref: str
    destination_ref: str

    def validate(self):
        if not self.intent_id or not self.purpose or not self.source_ref or not self.destination_ref:
            raise ValueError("intent, purpose, source and destination are required")
        if self.asset != "BTC":
            raise ValueError("only BTC-denominated proof intents are supported")
        if not isinstance(self.amount_msat, int) or isinstance(self.amount_msat, bool) or self.amount_msat <= 0:
            raise ValueError("amount_msat must be a positive integer")


def initial_ledger() -> dict:
    return {"schema": SCHEMA, "events": [], "head": None,
            "forward_intents": [], "backward_intents": []}


def _append(ledger: dict, event: dict) -> dict:
    if ledger.get("schema") != SCHEMA:
        raise ValueError("unsupported ledger schema")
    if not verify_ledger(ledger)["valid"]:
        raise ValueError("ledger integrity check failed")
    body = {**event, "sequence": len(ledger["events"]) + 1,
            "previous_hash": ledger.get("head"),
            "recorded_at": datetime.now(timezone.utc).isoformat()}
    event_hash = digest(body)
    record = {**body, "event_hash": event_hash}
    return {**ledger, "events": [*ledger["events"], record], "head": event_hash}


def record_forward(ledger: dict, intent: GrowthIntent, *, evidence: dict,
                   both_ends_verified: bool, approval_ref: str | None = None) -> dict:
    intent.validate()
    if intent.intent_id in ledger.get("forward_intents", []):
        raise ValueError("forward direction already recorded for this intent")
    if not both_ends_verified or not evidence.get("source_receipt") or not evidence.get("destination_receipt"):
        raise ValueError("both source and destination receipts are required")
    if not approval_ref:
        raise ValueError("explicit approval reference is required")
    event = {"kind": "FORWARD_INTENT_RECORDED", "direction": "FORWARD",
             "intent": intent.__dict__, "evidence": evidence,
             "approval_ref": approval_ref, "live_payment_performed": False, "live_refund_performed": False}
    result = _append(ledger, event)
    return {**result, "forward_intents": [*ledger.get("forward_intents", []), intent.intent_id]}


def record_backward(ledger: dict, intent: GrowthIntent, *, evidence: dict,
                    both_ends_verified: bool, approval_ref: str | None = None) -> dict:
    intent.validate()
    if intent.intent_id not in ledger.get("forward_intents", []):
        raise ValueError("backward direction requires a recorded forward intent")
    if intent.intent_id in ledger.get("backward_intents", []):
        raise ValueError("backward direction already recorded; only once is permitted")
    if not both_ends_verified or not evidence.get("source_receipt") or not evidence.get("destination_receipt"):
        raise ValueError("both source and destination receipts are required")
    if not approval_ref:
        raise ValueError("explicit approval reference is required")
    event = {"kind": "BACKWARD_REVERSAL_RECORDED", "direction": "BACKWARD",
             "intent": intent.__dict__, "evidence": evidence,
             "approval_ref": approval_ref, "live_payment_performed": False,
             "live_refund_performed": False,
             "links_to_forward": intent.intent_id}
    result = _append(ledger, event)
    return {**result, "backward_intents": [*ledger.get("backward_intents", []), intent.intent_id]}


def verify_ledger(ledger: dict) -> dict:
    if not isinstance(ledger, dict) or ledger.get("schema") != SCHEMA:
        return {"valid": False, "events": 0, "head": None}
    previous = None
    valid = True
    forwards, backwards = [], []
    for index, record in enumerate(ledger.get("events", []), 1):
        body = {k: v for k, v in record.items() if k != "event_hash"}
        valid = valid and record.get("sequence") == index
        valid = valid and record.get("previous_hash") == previous
        valid = valid and record.get("event_hash") == digest(body)
        valid = valid and record.get("direction") in DIRECTIONS
        valid = valid and record.get("live_payment_performed") is False
        valid = valid and record.get("live_refund_performed") is False
        iid = record.get("intent", {}).get("intent_id")
        if record.get("direction") == "FORWARD":
            valid = valid and iid not in forwards
            forwards.append(iid)
        else:
            valid = valid and iid in forwards and iid not in backwards
            backwards.append(iid)
            valid = valid and record.get("links_to_forward") == iid
        previous = record.get("event_hash")
    valid = valid and ledger.get("head") == previous
    valid = valid and ledger.get("forward_intents") == forwards
    valid = valid and ledger.get("backward_intents") == backwards
    return {"valid": bool(valid), "events": len(ledger.get("events", [])),
            "forward_count": len(forwards), "backward_count": len(backwards),
            "head": previous, "live_funds_moved": False}


def reconcile(ledger: dict) -> dict:
    proof = verify_ledger(ledger)
    if not proof["valid"]:
        return {"status": "INVALID_LEDGER", **proof}
    forward = set(ledger["forward_intents"])
    backward = set(ledger["backward_intents"])
    return {"status": "RECONCILED", "forward_only": sorted(forward - backward),
            "reversed_once": sorted(forward & backward),
            "orphan_reversals": sorted(backward - forward),
            "both_ends_policy": "SOURCE_AND_DESTINATION_RECEIPTS_REQUIRED",
            "live_funds_moved": False}

#!/usr/bin/env python3
"""Meta Guardian: unified, read-only production readiness evidence collector.

No deployment, wallet signing, payment, mutation, or credential output is performed.
External probes run only for explicitly configured targets. A read-only GitHub token
is optional and is used only to enumerate repositories and branches visible to it.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import socket
import ssl
import subprocess
import urllib.error
import urllib.request
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import urlparse


def truthy(name: str) -> bool:
    return os.getenv(name, "").strip().lower() in {"1", "true", "yes", "on"}


def tls_probe(host: str, port: int = 443, timeout: float = 4.0) -> dict:
    ctx = ssl.create_default_context()
    try:
        with socket.create_connection((host, port), timeout=timeout) as raw:
            with ctx.wrap_socket(raw, server_hostname=host) as tls:
                cert = tls.getpeercert()
                return {"status": "PASS", "host": host, "port": port,
                        "tls_version": tls.version(),
                        "certificate_subject_present": bool(cert.get("subject"))}
    except Exception as exc:
        return {"status": "FAIL", "host": host, "port": port,
                "error_type": type(exc).__name__}


def configured_https_endpoint(name: str) -> tuple[str | None, str]:
    value = os.getenv(name, "").strip()
    if not value:
        return None, "NOT_CONFIGURED"
    parsed = urlparse(value)
    if parsed.scheme != "https" or not parsed.hostname:
        return value, "INVALID_REQUIRES_HTTPS"
    return value, "CONFIGURED"


def github_get(path: str, token: str) -> object:
    request = urllib.request.Request(
        "https://api.github.com" + path,
        headers={"Accept": "application/vnd.github+json",
                 "Authorization": "Bearer " + token,
                 "X-GitHub-Api-Version": "2022-11-28",
                 "User-Agent": "MetaGuardian-ReadOnly-Auditor"}
    )
    with urllib.request.urlopen(request, timeout=8) as response:
        return json.loads(response.read().decode("utf-8"))


def discover_github_tree(token: str | None) -> dict:
    if not token:
        return {"status": "NOT_CONFIGURED", "repositories": [],
                "note": "Set META_GUARDIAN_GITHUB_READ_TOKEN with metadata:read access to enumerate the full accessible tree"}
    try:
        repositories = github_get("/user/repos?per_page=100&sort=updated", token)
        if not isinstance(repositories, list):
            raise ValueError("unexpected_repository_response")
        result = []
        for repo in repositories:
            full_name = repo.get("full_name", "")
            if not full_name:
                continue
            try:
                branches = github_get("/repos/" + full_name + "/branches?per_page=100", token)
                branch_names = [b.get("name", "") for b in branches if b.get("name")]
                branch_status = "DISCOVERED"
            except Exception as exc:
                branch_names = []
                branch_status = "UNAVAILABLE_" + type(exc).__name__
            result.append({
                "name": full_name,
                "default_branch": repo.get("default_branch"),
                "visibility": repo.get("visibility", "unknown"),
                "archived": bool(repo.get("archived", False)),
                "branches": branch_names,
                "branch_discovery": branch_status
            })
        return {"status": "DISCOVERED", "repository_count": len(result),
                "repositories": result,
                "scope_note": "GitHub repositories and up to 100 branches per repository visible to the supplied read-only token"}
    except Exception as exc:
        return {"status": "DISCOVERY_FAILED", "repositories": [],
                "error_type": type(exc).__name__,
                "note": "Token value is never emitted"}


def discover_local_repositories(root: Path) -> list[dict]:
    found = []
    for child in sorted(root.iterdir() if root.exists() else []):
        if child.is_dir() and (child / ".git").exists():
            try:
                branch = subprocess.run(
                    ["git", "-C", str(child), "branch", "--show-current"],
                    capture_output=True, text=True, timeout=3, check=False
                ).stdout.strip()
            except Exception:
                branch = ""
            found.append({"name": child.name, "branch": branch or "DETACHED_OR_UNKNOWN"})
    if (root / ".git").exists():
        try:
            branch = subprocess.run(
                ["git", "-C", str(root), "branch", "--show-current"],
                capture_output=True, text=True, timeout=3, check=False
            ).stdout.strip()
        except Exception:
            branch = ""
        found.insert(0, {"name": root.name, "branch": branch or "DETACHED_OR_UNKNOWN"})
    return found


def build_report(root: Path) -> dict:
    checks = {}
    guardian_url, guardian_cfg = configured_https_endpoint("META_GUARDIAN_CONTROL_PLANE_URL")
    checks["production_guardian"] = {
        "status": "PENDING" if not (truthy("META_GUARDIAN_ENABLED") and guardian_cfg == "CONFIGURED")
                  else "CONFIGURED_NOT_INTEGRATION_VERIFIED",
        "enabled": truthy("META_GUARDIAN_ENABLED"),
        "endpoint_state": guardian_cfg,
        "endpoint_host": urlparse(guardian_url).hostname if guardian_url else None,
        "evidence_required": "authenticated integration and deny-by-default authorization tests"
    }

    def probe_targets(variable: str) -> tuple[list[str], list[dict]]:
        targets = [x.strip() for x in os.getenv(variable, "").split(",") if x.strip()]
        results = []
        for target in targets:
            host, _, port_text = target.rpartition(":")
            if not host:
                host, port_text = target, "443"
            try:
                results.append(tls_probe(host, int(port_text or "443")))
            except ValueError:
                results.append({"status": "FAIL", "target": target, "error_type": "InvalidPort"})
        return targets, results

    tls_targets, tls_results = probe_targets("META_GUARDIAN_TLS_TARGETS")
    checks["live_tls_host_security"] = {
        "status": "NOT_CONFIGURED" if not tls_targets else
                  "PASS" if all(x["status"] == "PASS" for x in tls_results) else "FAIL",
        "probes": tls_results, "host_hardening": "NOT_ASSESSED",
        "note": "TLS handshake only; no port scan or intrusive host test"
    }

    btc_url, btc_cfg = configured_https_endpoint("BITCOIN_RPC_URL")
    checks["bitcoin_core"] = {
        "status": "NOT_CONFIGURED" if not os.getenv("BITCOIN_RPC_URL") else
                  "CONFIGURED_READ_ONLY_CHECK_REQUIRED" if btc_cfg == "CONFIGURED" else "INVALID_CONFIGURATION",
        "endpoint_host": urlparse(btc_url).hostname if btc_url else None,
        "credentials_present": bool(os.getenv("BITCOIN_RPC_USER") and os.getenv("BITCOIN_RPC_PASSWORD")),
        "rpc_probe": "NOT_RUN_BY_DEFAULT",
        "note": "No RPC call is made; a separately authorized read-only probe is required"
    }
    lnd_url, lnd_cfg = configured_https_endpoint("LND_REST_URL")
    checks["lightning"] = {
        "status": "NOT_CONFIGURED" if not os.getenv("LND_REST_URL") else
                  "CONFIGURED_NOT_CONNECTED" if lnd_cfg == "CONFIGURED" else "INVALID_CONFIGURATION",
        "endpoint_host": urlparse(lnd_url).hostname if lnd_url else None,
        "macaroon_path_present": bool(os.getenv("LND_MACAROON_PATH") and Path(os.getenv("LND_MACAROON_PATH", "")).is_file()),
        "connection": "NOT_TESTED"
    }

    api_targets, api_results = probe_targets("META_GUARDIAN_API_TLS_TARGETS")
    checks["wallet_external_api_security"] = {
        "status": "NOT_CONFIGURED" if not api_targets else
                  "TLS_PASS_SECURITY_REVIEW_REQUIRED" if all(x["status"] == "PASS" for x in api_results) else "TLS_FAIL",
        "tls_probes": api_results, "key_handling_auth_replay_rate_limit": "NOT_ASSESSED",
        "wallet_operations_performed": False
    }
    checks["production_deployment"] = {
        "status": "BLOCKED_NOT_AUTHORIZED",
        "authorization_flag_present": truthy("PRODUCTION_DEPLOYMENT_AUTHORIZED"),
        "deployment_performed": False,
        "note": "This tool never deploys; a separate authorized release process is required"
    }

    attestation = os.getenv("INDEPENDENT_AUDIT_ATTESTATION", "").strip()
    attestation_path = Path(attestation) if attestation else None
    checks["independent_production_audit"] = {
        "status": "ATTESTATION_FILE_PRESENT_REVIEW_REQUIRED" if attestation_path and attestation_path.is_file() else "OPEN",
        "attestation_file_present": bool(attestation_path and attestation_path.is_file()),
        "signature_independently_verified": False
    }

    local_repos = discover_local_repositories(root)
    github_tree = discover_github_tree(os.getenv("META_GUARDIAN_GITHUB_READ_TOKEN"))
    checks["repository_tree_discovery"] = {
        "status": github_tree["status"] if github_tree["status"] != "NOT_CONFIGURED" else
                  "LOCAL_ONLY" if local_repos else "NOT_CONFIGURED",
        "local_repositories": local_repos,
        "github": github_tree
    }

    blockers = [{"workstream": key, "status": item["status"]}
                for key, item in checks.items()
                if item["status"] not in {"PASS", "DISCOVERED", "LOCAL_ONLY"}]
    report = {
        "schema": "meta-guardian-readiness/v1",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "mode": "READ_ONLY_EVIDENCE_COLLECTION",
        "checks": checks, "blockers": blockers,
        "release_decision": "NOT_PRODUCTION_READY",
        "safety": {
            "network_probes_only_for_explicitly_configured_targets": True,
            "credentials_or_secret_values_emitted": False,
            "wallet_or_payment_actions": False,
            "deployment_or_mutation_actions": False
        }
    }
    canonical = json.dumps(report, sort_keys=True, separators=(",", ":")).encode()
    report["report_sha256"] = hashlib.sha256(canonical).hexdigest()
    return report


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", default=".", help="Workspace root to discover local repositories")
    parser.add_argument("--output", default="meta-guardian-report.json")
    args = parser.parse_args()
    report = build_report(Path(args.root).resolve())
    output = Path(args.output)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(json.dumps({"report": str(output), "release_decision": report["release_decision"],
                      "workstreams": len(report["checks"]), "blockers": len(report["blockers"]),
                      "sha256": report["report_sha256"]}, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""NRE-1 reversible byte transform. This is encoding, not encryption."""
from __future__ import annotations
import struct
import zlib

MAGIC = b"NRE1"
MODULUS = 256
MATRIX = ((3, 1, 4), (1, 5, 9), (3, 6, 5))
INVERSE = ((89, 233, 175), (162, 185, 203), (213, 99, 10))
BLOCK = 3


def _transform(block: bytes, matrix) -> bytes:
    if len(block) != BLOCK:
        raise ValueError("NRE-1 operates on exactly three-byte blocks")
    return bytes(sum(matrix[r][c] * block[c] for c in range(BLOCK)) % MODULUS
                 for r in range(BLOCK))


def encode(data: bytes) -> bytes:
    if not isinstance(data, bytes):
        raise TypeError("data must be bytes")
    padded_len = ((len(data) + BLOCK - 1) // BLOCK) * BLOCK
    padded = data + b"\x00" * (padded_len - len(data))
    transformed = b"".join(_transform(padded[i:i + BLOCK], MATRIX)
                           for i in range(0, padded_len, BLOCK))
    return MAGIC + struct.pack(">I", len(data)) + transformed + struct.pack(">I", zlib.crc32(data))


def decode(frame: bytes) -> bytes:
    if not isinstance(frame, bytes) or len(frame) < 12 or frame[:4] != MAGIC:
        raise ValueError("invalid NRE-1 frame header")
    length = struct.unpack(">I", frame[4:8])[0]
    encoded = frame[8:-4]
    crc = struct.unpack(">I", frame[-4:])[0]
    if len(encoded) % BLOCK or len(encoded) != ((length + BLOCK - 1) // BLOCK) * BLOCK:
        raise ValueError("invalid NRE-1 frame length")
    decoded = b"".join(_transform(encoded[i:i + BLOCK], INVERSE)
                       for i in range(0, len(encoded), BLOCK))[:length]
    if zlib.crc32(decoded) != crc:
        raise ValueError("NRE-1 CRC-32 mismatch")
    return decoded


def verify_round_trip(data: bytes) -> dict:
    frame = encode(data)
    recovered = decode(frame)
    return {"valid": recovered == data, "input_bytes": len(data),
            "frame_bytes": len(frame), "crc32": f"{zlib.crc32(data):08x}"}

import unittest
from tools.nre1 import encode, decode, verify_round_trip, MATRIX, INVERSE

class NRE1Tests(unittest.TestCase):
    def test_empty_payload(self):
        self.assertEqual(decode(encode(b"")), b"")

    def test_round_trip_all_lengths(self):
        for size in range(0, 40):
            payload = bytes((i * 37) % 256 for i in range(size))
            self.assertEqual(decode(encode(payload)), payload)

    def test_binary_round_trip(self):
        payload = bytes(range(256))
        self.assertEqual(decode(encode(payload)), payload)

    def test_corruption_rejected(self):
        frame = bytearray(encode(b"mirror-parallel-proof"))
        frame[8] ^= 1
        with self.assertRaisesRegex(ValueError, "CRC-32"):
            decode(bytes(frame))

    def test_header_rejected(self):
        with self.assertRaisesRegex(ValueError, "header"):
            decode(b"NOPE" + encode(b"x")[4:])

    def test_empty_truncated_frame_rejected(self):
        with self.assertRaises(ValueError):
            decode(b"NRE1" + b"\\x00" * 4)

    def test_truncated_frame_rejected(self):
        with self.assertRaises(ValueError):
            decode(encode(b"abc")[:-1])

    def test_matrix_inverse_mod_256(self):
        for r in range(3):
            for c in range(3):
                actual = sum(INVERSE[r][k] * MATRIX[k][c] for k in range(3)) % 256
                self.assertEqual(actual, int(r == c))

    def test_report(self):
        self.assertTrue(verify_round_trip(b"Paradox 4D Mirror")["valid"])

if __name__ == "__main__":
    unittest.main()
